    "achète un dieu dans le shop": "kauf einen Gott im Shop",
    "achève les ennemis presque morts et chance de coup critique (+{critBonus}% de dégâts critiques)": "erledigt fast besiegte Gegner und Chance auf kritischen Treffer (+{critBonus}% Krit-Schaden)",
    "achève les ennemis presque morts et enracine les ennemis autour": "erledigt fast besiegte Gegner und verwurzelt Gegner in der Nähe",
    "achève les ennemis presque morts et laisse des braises au sol": "erledigt fast besiegte Gegner und hinterlässt Glut am Boden",
    "achève les ennemis presque morts et repousse les ennemis autour": "erledigt fast besiegte Gegner und stößt Gegner in der Nähe zurück",
    "achève les ennemis presque morts et un tourbillon attire les ennemis vers l'impact": "erledigt fast besiegte Gegner und ein Wirbel zieht Gegner zum Einschlag",
    "achève les ennemis presque morts, chance de coup critique (+{critBonus}% de dégâts critiques) et fait saigner l'ennemi (les saignements s'additionnent)": "erledigt fast besiegte Gegner, Chance auf kritischen Treffer (+{critBonus}% Krit-Schaden) und lässt den Gegner bluten (Blutungen stapeln sich)",
    "achève les ennemis presque morts, fait brûler l'ennemi et rebondit sur un autre ennemi": "erledigt fast besiegte Gegner, setzt den Gegner in Brand und springt auf einen weiteren Gegner über",
    "achève les ennemis presque morts, la balle revient vers sa planète en touchant tout sur son passage et chance de coup critique (+{critBonus}% de dégâts critiques)": "erledigt fast besiegte Gegner, die Kugel fliegt zu ihrem Planeten zurück (und trifft alles auf dem Weg) und Chance auf kritischen Treffer (+{critBonus}% Krit-Schaden)",
    "braises au sol, critiques, et achève les ennemis presque morts": "Glut am Boden, kritische Treffer und erledigt fast besiegte Gegner",
    "chance de coup critique (+{critBonus}% de dégâts critiques), achève les ennemis presque morts et recharge ton bouclier plus vite": "Chance auf kritischen Treffer (+{critBonus}% Krit-Schaden), erledigt fast besiegte Gegner und lädt deinen Schild schneller auf",
    "chance de coup critique (+{critBonus}% de dégâts critiques), et les ennemis brûlent": "Chance auf kritischen Treffer (+{critBonus}% Krit-Schaden), und die Gegner brennen",
    "chance de coup critique (+{critBonus}% de dégâts critiques), te soigne à chaque coup et frappe une 2e fois un instant plus tard": "Chance auf kritischen Treffer (+{critBonus}% Krit-Schaden), heilt dich bei jedem Treffer und trifft kurz darauf ein 2. Mal",
    "chance de renvoyer l'ennemi au bord de l'écran, et il est ralenti": "Chance, den Gegner an den Bildschirmrand zurückzuschicken, und er wird verlangsamt",
    "chance de renvoyer l'ennemi au bord de l'écran, et repousse tout autour": "Chance, den Gegner an den Bildschirmrand zurückzuschicken, und stößt alles in der Nähe zurück",
