    "Flèche de lune : toutes les {@PLANET_POWERS.moonArrow.interval} s, Artémis tire une grande flèche qui transperce tous les ennemis sur son passage ({moonArrow} fois les dégâts d'une balle)": "Mondpfeil: Alle {@PLANET_POWERS.moonArrow.interval} s schießt Artemis einen großen Pfeil, der alle Gegner auf seinem Weg durchbohrt ({moonArrow}-facher Kugelschaden)",
    "Rebond : les balles d'Artémis rebondissent sur {bounce} autres ennemis proches": "Abprall: Artemis' Kugeln prallen auf {bounce} weitere nahe Gegner ab",
    "Flèche de lune : +{moonArrow} fois les dégâts d'une balle": "Mondpfeil: +{moonArrow}-facher Kugelschaden",
    "+{bounce} rebond et +{attackSpeed:%}% de vitesse d'attaque": "+{bounce} Abprall und +{attackSpeed:%}% Angriffstempo",
    "Foudre : un ennemi conducteur touché par un 2e éclair reçoit la foudre ({boltDamage} fois les dégâts de la balle), qui électrocute les ennemis autour : ils deviennent conducteurs à leur tour": "Blitz: Ein leitender Gegner, den ein 2. Lichtbogen trifft, wird vom Blitz getroffen ({boltDamage}-facher Kugelschaden), der Gegner in der Nähe elektrisiert: Sie werden ihrerseits leitend",
    "la foudre fait +{boltDamage} fois les dégâts de la balle et électrocute {boltRadius:%}% plus loin": "der Blitz macht +{boltDamage}-fachen Kugelschaden und elektrisiert {boltRadius:%}% weiter",
