    "Éclairs : +{arcDamage:%}% de dégâts": "Lichtbögen: +{arcDamage:%}% Schaden",
    "Arc électrique : chaque balle de Zeus qui touche envoie un éclair vers un ennemi proche ({arcDamage:%}% des dégâts), qui devient conducteur": "Lichtbogen: Jede Kugel von Zeus, die trifft, schickt einen Lichtbogen zu einem nahen Gegner ({arcDamage:%}% Schaden), der leitend wird",
