    "chaque ennemi tué par Arès lui donne +{damagePerKill} dégât de plus, pour toujours, et cri de guerre {warCry:x} fois plus fort": "jeder von Ares besiegte Gegner gibt ihm für immer +{damagePerKill} Schaden mehr, und Kriegsschrei {warCry:x}-mal so stark",
