    "Chasseur de monstres": "Monsterjäger",
    "Héros de l'Olympe": "Held des Olymp",
    "Favori des dieux": "Liebling der Götter",
    "Fléau des Titans": "Geißel der Titanen",
    "Demi-dieu": "Halbgott",
